// ---------------- inputs: MIC 1, MIC 2, LINE IN ----------------
const inputs = [
  { key: 'mic1', name: 'MIC 1', btn: '#mic1', sel: '#dev1', voice: true, chain: null, on: false },
  { key: 'mic2', name: 'MIC 2', btn: '#mic2', sel: '#dev2', voice: true, chain: null, on: false },
  { key: 'line', name: 'LINE IN', btn: '#lineBtn', sel: '#devLine', voice: false, chain: null, on: false }];
let micLinked = store.get('micLink', '0') === '1', lineMon = store.get('lineMon', '0') === '1';
const lineGain = () => (+$('#lineR').value || 0) / 100;
async function openInput(inp){
  const id = store.get('dev_' + inp.key, '');
  const cons = { deviceId: id ? { exact: id } : undefined, echoCancellation: false, noiseSuppression: false, autoGainControl: false };
  if (!inp.voice) cons.channelCount = { ideal: 2 };
  const stream = await navigator.mediaDevices.getUserMedia({ audio: cons });
  closeInput(inp);
  const src = ctx.createMediaStreamSource(stream);
  let last = src;
  if (inp.voice) {
    const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 80;
    const comp = ctx.createDynamicsCompressor(); comp.threshold.value = -24; comp.ratio.value = 4; comp.attack.value = 0.005; comp.release.value = 0.2; comp.knee.value = 6;
    const makeup = ctx.createGain(); makeup.gain.value = 1.6;
    src.connect(hp); hp.connect(comp); comp.connect(makeup); last = makeup;
  }
  const level = ctx.createGain(); level.gain.value = inp.voice ? 1 : lineGain();
  const onG = ctx.createGain(); onG.gain.value = 0;
  last.connect(level); level.connect(onG); onG.connect(masterIn);
  if (!inp.voice && lineMon) onG.connect(monitor);
  inp.chain = { stream, src, level, onG };
  listDevices();
}
function closeInput(inp){ if (!inp.chain) return; inp.chain.stream.getTracks().forEach(t => t.stop()); try { inp.chain.onG.disconnect(); inp.chain.src.disconnect(); } catch(e){} inp.chain = null; }
async function setInput(inp, on){
  if (!ctx) return false;
  if (on && !inp.chain) { try { await openInput(inp); } catch(e){ toast(inp.name + ': cannot open this input. Allow microphone access or pick another input in Settings ⚙'); return false; } }
  inp.on = on; if (inp.chain) inp.chain.onG.gain.setTargetAtTime(on ? 1 : 0, ctx.currentTime, 0.02);
  applyDuck(); renderInputs(); return true;
}
async function toggleMicN(n){
  const target = !inputs[n].on;
  if (micLinked) await Promise.all([setInput(inputs[0], target), setInput(inputs[1], target)]);
  else await setInput(inputs[n], target);
}
function applyDuck(){
  micOn = inputs[0].on || inputs[1].on;
  if (ctx) musicBus.gain.setTargetAtTime(micOn ? duckGain() : 1, ctx.currentTime, micOn ? 0.08 : 0.25);
}
function renderInputs(){
  [0, 1].forEach(i => { const b = $(inputs[i].btn); b.classList.toggle('on', inputs[i].on); b.querySelector('.ms').textContent = inputs[i].on ? 'LIVE' : 'OFF'; });
  $('#micLink').classList.toggle('on', micLinked); $('#micLink').setAttribute('aria-pressed', String(micLinked));
  $('#lineBtn').classList.toggle('on', inputs[2].on);
  $('#micS').textContent = micOn ? 'Music ducked −' + $('#duckR').value + ' dB' : (micLinked ? 'Linked · Space = both mics' : 'Space = MIC 1 · Shift+Space = MIC 2');
}
$('#mic1').onclick = () => toggleMicN(0);
$('#mic2').onclick = () => toggleMicN(1);
$('#micLink').onclick = async () => { micLinked = !micLinked; store.set('micLink', micLinked ? '1' : '0');
  if (micLinked && inputs[1].on !== inputs[0].on) await setInput(inputs[1], inputs[0].on); renderInputs(); };
$('#lineBtn').onclick = () => setInput(inputs[2], !inputs[2].on);
$('#lineR').value = store.get('lineLvl', '100');
function showLine(){ const v = +$('#lineR').value; $('#lineV').textContent = v === 0 ? '−∞' : (20 * Math.log10(v / 100)).toFixed(1) + ' dB'; $('#lineR').style.setProperty('--p', (v / 150 * 100) + '%'); }
showLine();
$('#lineR').oninput = () => { showLine(); store.set('lineLvl', $('#lineR').value); const c = inputs[2].chain; if (c && ctx) c.level.gain.setTargetAtTime(lineGain(), ctx.currentTime, 0.03); };
$('#lineMon').classList.toggle('on', lineMon);
$('#lineMon').onclick = () => { lineMon = !lineMon; store.set('lineMon', lineMon ? '1' : '0'); $('#lineMon').classList.toggle('on', lineMon);
  const c = inputs[2].chain; if (c && ctx) { if (lineMon) c.onG.connect(monitor); else { try { c.onG.disconnect(monitor); } catch(e){} } } };
async function listDevices(askPermission){
  if (!navigator.mediaDevices) return;
  let devs = await navigator.mediaDevices.enumerateDevices().catch(() => []);
  if (askPermission && !devs.some(d => d.kind === 'audioinput' && d.label)) {
    try { const st = await navigator.mediaDevices.getUserMedia({ audio: true }); st.getTracks().forEach(t => t.stop()); devs = await navigator.mediaDevices.enumerateDevices(); } catch(e){}
  }
