  inputs.forEach(inp => { const sel = $(inp.sel), cur = store.get('dev_' + inp.key, '');
    sel.innerHTML = '<option value="">Default input</option>' + ins.filter(d => d.deviceId && d.deviceId !== 'default').map((d, i) => `<option value="${esc(d.deviceId)}">${esc(d.label || 'Input ' + (i + 1))}</option>`).join('');
    sel.value = cur; if (sel.value !== cur) sel.value = ''; });
}
inputs.forEach(inp => { $(inp.sel).onchange = async () => { store.set('dev_' + inp.key, $(inp.sel).value);
