// ---------------- broadcast (MP3 encoder → server) ----------------
let live = false, enc = null, outBuf = [], sending = false, lastOk = 0;
function setupEncoder(){
  const sp = ctx.createScriptProcessor(4096, 2, 2);
  masterOut.connect(sp);
  const mute = ctx.createGain(); mute.gain.value = 0; sp.connect(mute); mute.connect(ctx.destination);
  sp.onaudioprocess = e => {
    if (!live || !enc) return;
    const L = e.inputBuffer.getChannelData(0), R = e.inputBuffer.getChannelData(1), n = L.length;
    const l = new Int16Array(n), r = new Int16Array(n);
    for (let i=0;i<n;i++){ l[i] = Math.max(-1, Math.min(1, L[i])) * 32767; r[i] = Math.max(-1, Math.min(1, R[i])) * 32767; }
    const mp3 = enc.encodeBuffer(l, r); if (mp3.length) outBuf.push(new Uint8Array(mp3));
  };
}
async function flush(){
  if (!live || sending || !outBuf.length) return;
  const parts = outBuf; outBuf = [];
  const len = parts.reduce((a, b) => a + b.length, 0), body = new Uint8Array(len); let o = 0; parts.forEach(p => { body.set(p, o); o += p.length; });
  sending = true;
  try {
    const r = await fetch('/api/push', { method: 'POST', headers: { 'X-Radio-Key': KEY(), 'Content-Type': 'audio/mpeg' }, body });
    if (r.status === 401) { toast('Wrong broadcast password'); goLive(false); }
    else { lastOk = Date.now(); }
  } catch(e){ setSrv(false); }
  sending = false;
}
setInterval(flush, 400);

