let lastReqId = null, newReqs = [];
function beep(){ try { if (!ctx) return; const o = ctx.createOscillator(), g = ctx.createGain(); o.frequency.value = 880; g.gain.setValueAtTime(0.0001, ctx.currentTime); g.gain.exponentialRampToValueAtTime(0.15, ctx.currentTime + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.35); o.connect(g); g.connect(ctx.destination); o.start(); o.stop(ctx.currentTime + 0.4); } catch(e){} }
function checkRequests(list){
  const maxId = list.reduce((m, r) => Math.max(m, r.id || 0), 0);
  if (lastReqId === null || maxId < lastReqId) { lastReqId = maxId; return; }
  const fresh = list.filter(r => (r.id || 0) > lastReqId).sort((a, b) => a.id - b.id);
  if (!fresh.length) return;
  lastReqId = maxId; newReqs.push(...fresh);
