// ---------------- Spotify (preview player, your account) ----------------
const SP = { token: store.get('spTok', ''), refresh: store.get('spRef', ''), exp: +store.get('spExp', '0'), player: null, device: '', state: null, results: [], err: '' };
const SP_REDIRECT = location.origin + '/spotify-callback';
const PLAYI = '<svg width="16" height="16" viewBox="0 0 24 24" fill="#0D0E11"><path d="M7 4.5v15l13-7.5z"/></svg>', PAUSEI = '<svg width="16" height="16" viewBox="0 0 24 24" fill="#0D0E11"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>';
const b64url = buf => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
async function cfgGet(){ const r = await fetch('/api/config', { headers: { 'X-Radio-Key': KEY() } }); if (!r.ok) throw new Error('auth'); return r.json(); }
async function spConnect(){
  if (SP.refresh) { spLogout(); return; }
  let c; try { c = await cfgGet(); } catch(e){ toast('Enter the broadcast password in Settings ⚙ first'); return; }
  if (!c.spotifyId) { toast('Add your Spotify Client ID in Settings ⚙'); return; }
  store.set('spCid', c.spotifyId);
  const v = b64url(crypto.getRandomValues(new Uint8Array(48))); store.set('spVer', v);
  const ch = b64url(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(v)));
  const url = 'https://accounts.spotify.com/authorize?' + new URLSearchParams({ response_type: 'code', client_id: c.spotifyId, redirect_uri: SP_REDIRECT, code_challenge_method: 'S256', code_challenge: ch,
    scope: 'streaming user-read-email user-read-private user-read-playback-state user-modify-playback-state' });
  if (!window.open(url, 'spotify', 'width=480,height=720')) toast('Allow pop-ups for this page');
}
function spSave(t){ SP.token = t.access_token; if (t.refresh_token) SP.refresh = t.refresh_token; SP.exp = Date.now() + (t.expires_in || 3600) * 1000;
  store.set('spTok', SP.token); store.set('spRef', SP.refresh); store.set('spExp', String(SP.exp)); }
function spLogout(){ if (SP.player) SP.player.disconnect(); Object.assign(SP, { token: '', refresh: '', exp: 0, player: null, device: '', state: null, results: [] }); ['spTok','spRef','spExp'].forEach(k => store.set(k, '')); renderSp(); toast('Spotify disconnected'); }
window.addEventListener('message', async e => {
  if (e.origin !== location.origin || !e.data || !e.data.spotify) return;
  const d = e.data.spotify; if (d.error || !d.code) { toast('Spotify login cancelled'); return; }
  try { const r = await fetch('https://accounts.spotify.com/api/token', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ grant_type: 'authorization_code', code: d.code, redirect_uri: SP_REDIRECT, client_id: store.get('spCid', ''), code_verifier: store.get('spVer', '') }) });
    const t = await r.json(); if (!t.access_token) { toast('Spotify login failed: ' + (t.error_description || t.error || r.status)); return; }
    spSave(t); spStart(); toast('Spotify connected'); } catch(err){ toast('Spotify login failed'); }
});
async function spTok(){
  if (SP.token && Date.now() < SP.exp - 60000) return SP.token;
  if (!SP.refresh) return '';
  try { const r = await fetch('https://accounts.spotify.com/api/token', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: SP.refresh, client_id: store.get('spCid', '') }) });
    const t = await r.json(); if (t.access_token) { spSave(t); return SP.token; } } catch(e){}
  return '';
}
async function spApi(path, opt = {}){
  const tok = await spTok(); if (!tok) throw new Error('Not connected');
  const r = await fetch('https://api.spotify.com/v1' + path, Object.assign({}, opt, { headers: Object.assign({ Authorization: 'Bearer ' + tok }, opt.headers || {}) }));
  if (r.status === 204) return null; const j = await r.json().catch(() => null);
