    pl.addListener('ready', ({ device_id }) => { SP.device = device_id; SP.err = ''; renderSp(); });
    pl.addListener('not_ready', () => { SP.device = ''; renderSp(); });
    pl.addListener('player_state_changed', st => { SP.state = st; renderSp(); });
    ['initialization_error', 'authentication_error', 'account_error', 'playback_error'].forEach(ev => pl.addListener(ev, ({ message }) => { SP.err = ev === 'account_error' ? 'Spotify Premium is required for playback.' : message; renderSp(); }));
